# AI-generated by OpenAI Codex, 2026-11-15.
"""UI regressions against the real planner, including hidden-view and map contracts."""
import datetime as dt
import json
from pathlib import Path
import sys
import unittest

from streamlit.testing.v1 import AppTest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from sites import load_sites


def plotted(values):
    """Chart coordinates as a list. Newer Plotly versions store arrays as base64 binary."""
    if isinstance(values, dict) and "bdata" in values:
        import base64

        import numpy as np
        return np.frombuffer(base64.b64decode(values["bdata"]), dtype=values["dtype"]).tolist()
    return list(values)


class InterfaceTests(unittest.TestCase):
    def start(self):
        app = AppTest.from_file(str(ROOT / "src/app.py"), default_timeout=25).run()
        self.assertFalse(app.exception)
        return app

    def sites(self):
        app = self.start()
        app.button[0].click().run()
        self.assertFalse(app.exception)
        return app

    def test_empty_date_is_recoverable(self):
        app = self.start()
        app.date_input[0].set_value(None)
        app.button[0].click().run()
        self.assertFalse(app.exception)
        self.assertTrue(app.error)
        self.assertEqual(app.session_state.step, 1)

    def test_mission_survives_back_navigation(self):
        app = self.start()
        app.date_input[0].set_value(dt.date(2029, 6, 8))
        app.time_input[0].set_value(dt.time(17))
        app.slider[0].set_value(27)
        app.button[0].click().run()
        self.assertFalse(app.exception)
        next(b for b in app.button if b.label == "Change date").click().run()
        self.assertEqual(app.date_input[0].value, dt.date(2029, 6, 8))
        self.assertEqual(app.time_input[0].value, dt.time(17))
        self.assertEqual(app.slider[0].value, 27)

    def test_real_map_positions_and_image_extent(self):
        app = self.sites()
        spec = json.loads(app.get("plotly_chart")[0].proto.spec)
        points = spec["data"][-1]
        actual = load_sites().set_index("site")
        xs, ys = plotted(points["x"]), plotted(points["y"])
        self.assertEqual(len(xs), 13)
        for x, y, fields in zip(xs, ys, points["customdata"]):
            self.assertAlmostEqual(x, actual.loc[fields[0], "x_km"])
            self.assertAlmostEqual(y, actual.loc[fields[0], "y_km"])
        image = spec["layout"]["images"][0]
        self.assertEqual((image["x"], image["y"], image["sizex"], image["sizey"]), (-210, 210, 420, 420))
        self.assertTrue(image["source"].startswith("data:image/jpeg;base64,"))

    def test_hidden_views_are_not_rendered(self):
        app = self.sites()
        self.assertEqual(len(app.get("plotly_chart")), 2)
        self.assertEqual(len(app.number_input), 0)
        app.radio(key="workspace").set_value("Compare dates").run()
        self.assertFalse(app.exception)
        self.assertEqual(len(app.get("plotly_chart")), 1)
        spec = json.loads(app.get("plotly_chart")[0].proto.spec)
        self.assertEqual(len(spec["data"][0]["y"]), 13)
        self.assertEqual(len(spec["data"][0]["x"]), 366)
        self.assertEqual(len(app.number_input), 0)
        app.radio(key="workspace").set_value("Custom coordinates").run()
        self.assertFalse(app.exception)
        self.assertEqual(len(app.number_input), 2)
        self.assertEqual(len(app.get("plotly_chart")), 2)          # skyline panorama + elevation over time
        self.assertTrue(any("Terrain included" in w.value for w in app.info))

    def test_selection_and_hour_scrubbing(self):
        app = self.sites()
        app.selectbox(key="site_picker").set_value("Malapert Massif").run()
        self.assertFalse(app.exception)
        self.assertEqual(app.session_state.selected_site, "Malapert Massif")
        slider = next(s for s in app.slider if s.label.startswith("Explore the mission"))
        slider.set_value(48).run()
        self.assertFalse(app.exception)
        spec = json.loads(app.get("plotly_chart")[1].proto.spec)
        self.assertTrue(any(t.get("name") == "Sun at selected hour" for t in spec["data"]))
        next(r for r in app.radio if r.label == "Horizon view").set_value("Visibility over time").run()
        self.assertFalse(app.exception)

    def test_last_day_long_mission_and_failed_limits(self):
        app = self.start()
        app.date_input[0].set_value(dt.date(2030, 12, 31))
        app.time_input[0].set_value(dt.time(23))
        app.slider[0].set_value(60)
        app.button[0].click().run()
        self.assertFalse(app.exception)
        next(s for s in app.slider if s.label == "Maximum mean slope").set_value(1)
        next(b for b in app.button if b.label == "Apply criteria").click().run()
        self.assertFalse(app.exception)
        self.assertTrue(any("No site passes" in e.value for e in app.error))
        self.assertEqual(len(app.dataframe[0].value), 13)

    def test_zero_weights_show_fallback(self):
        app = self.sites()
        for label in ("Sunlight", "Earth contact", "Flatness"):
            next(s for s in app.slider if s.label == label).set_value(0.0)
        next(b for b in app.button if b.label == "Apply criteria").click().run()
        self.assertFalse(app.exception)
        self.assertTrue(any("equal weights" in w.value for w in app.warning))
        self.assertTrue(any("Sunlight 1" in c.value for c in app.caption))

    def test_settings_survive_unmounted_views(self):
        app = self.sites()
        app.slider(key="criterion_slope").set_value(7)
        next(b for b in app.button if b.label == "Apply criteria").click().run()
        app.radio(key="workspace").set_value("Custom coordinates").run()
        app.number_input(key="custom_lat").set_value(-86.25)
        app.number_input(key="custom_lon").set_value(18.5)
        next(b for b in app.button if b.label == "Evaluate coordinates").click().run()
        app.radio(key="workspace").set_value("Sites").run()
        app.radio(key="workspace").set_value("Custom coordinates").run()
        self.assertEqual(app.number_input(key="custom_lat").value, -86.25)
        self.assertEqual(app.number_input(key="custom_lon").value, 18.5)
        next(b for b in app.button if b.label == "Change date").click().run()
        app.button[0].click().run()
        self.assertFalse(app.exception)
        self.assertEqual(app.slider(key="criterion_slope").value, 7)


if __name__ == "__main__":
    unittest.main()
